package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.client.*;
import dev.tacticalcombat.uiapi.*;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.render.RenderTickCounter;
import net.minecraft.client.gui.screen.Screen;
import net.fabricmc.loader.api.FabricLoader;
import java.nio.file.Path;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

/** Tick-scheduled presentation using the existing shared request pump and authoritative events. */
public final class CubetableHud {
    public static final HudSession MODEL=new HudSession();
    private static HudPreferences prefs;
    private static HudOptions options;
    public static String error="";
    private static long ticks,generation,lease,lastRevalidate;
    private static int poll,delay;
    private static final PartyPages partyPages=new PartyPages();
    private static boolean pending,combat;
    private static String encounter="",role="";
    private static HudSession.Line dice,notice;
    private static long diceStart,noticeStart;
    private static List<HudSession.Line> log=List.of();
    private static boolean expanded;
    private CubetableHud(){}
    private static Path layoutPath(){return FabricLoader.getInstance().getConfigDir().resolve("tacticalcombat/hud-layout.json");}
    private static Path optionsPath(){return FabricLoader.getInstance().getConfigDir().resolve("tacticalcombat/hud-options.json");}
    public static HudPreferences preferences(){if(prefs==null){try{prefs=HudPreferences.load(layoutPath());}catch(Exception e){prefs=defaults();error="HUD layout could not be loaded; review settings before saving.";}}return prefs;}
    public static HudOptions options(){if(options==null){try{options=HudOptions.load(optionsPath());}catch(Exception e){options=HudOptions.defaults();error="HUD options could not be loaded; review settings before saving.";}}return options;}
    public static HudPreferences defaults(){return new HudPreferences(1,new HudPreferences.Panel(0,0,1,true),new HudPreferences.Panel(.5,0,1,true),new HudPreferences.Panel(.5,.45,1,true),new HudPreferences.Panel(0,.88,1,true),9,1,false,true);}
    public static void save(HudPreferences next,HudOptions extra)throws java.io.IOException{next.save(layoutPath());extra.save(optionsPath());prefs=next;options=extra;}
    public static void clear(){generation++;MODEL.clear();partyPages.clear();pending=false;combat=false;encounter="";role="";lease=0;poll=0;delay=0;dice=null;notice=null;log=List.of();fallback.clear();}
    public static boolean campaignEvents(){return ClientUiApi.supported()&&!MODEL.campaign().isBlank();}
    public static boolean replacesInitiative(){return preferences().visible()&&preferences().initiative().visible()&&!MODEL.actors().isEmpty();}
    public static void skip(){if(dice!=null)diceStart=ticks-animationTicks();}
    public static void toggleLog(){expanded=!expanded;}
    private static int animationTicks(){return preferences().reducedMotion()?1:Math.clamp((int)(24/preferences().animationSpeed()),6,96);}
    public static void tick(MinecraftClient client){ticks++;preferences();options();if(client.player==null){clear();return;}if(dice!=null&&ticks-diceStart>animationTicks()+50)dice=null;var queued=MODEL.nextDice();if(queued!=null&&queued.kind().equals("CHARACTER_CHECK")){DiceAnimation.enqueueEvent(queued);queued=null;}if(queued!=null&&queued.kind().equals("DICE"))queued=null;if(queued!=null){if(dice==null){dice=queued;diceStart=ticks;}else legacyQueue(queued);}if(dice==null&&!fallback.isEmpty()){dice=fallback.pollFirst();diceStart=ticks;}if(options().legacyDice()){dice=null;fallback.clear();}if(notice!=null&&ticks-noticeStart>options().notificationTicks())notice=null;if(notice==null){notice=MODEL.nextNotice();noticeStart=ticks;if(notice!=null&&options().sound()&&options().notificationsVisible())client.getSoundManager().play(net.minecraft.client.sound.PositionedSoundInstance.master(net.minecraft.sound.SoundEvents.ENTITY_EXPERIENCE_ORB_PICKUP,1f));}if(!ClientUiApi.supported()){if(!MODEL.campaign().isBlank())clear();return;}if(lease>0&&ticks>lease){clear();}
        if(!prefs.visible()||pending)return;if(delay>0){delay--;return;}if(client.currentScreen instanceof RpgScreen&&!(client.currentScreen instanceof HudLogScreen)&&!(client.currentScreen instanceof HudEventScreen)&&!(client.currentScreen instanceof PartyHudScreen))return;
        if(ticks-lastRevalidate>=200&&!MODEL.campaign().isBlank()&&!MODEL.catchingUp()){MODEL.revalidateHistory();lastRevalidate=ticks;dice=null;notice=null;fallback.clear();}
        var op=switch(poll){case 0->ACTIVE;case 1->CAMPAIGN_GET;case 2->PARTY;case 3->EVENTS;default->INITIATIVE;};
        if(poll>0&&MODEL.campaign().isBlank()){poll=0;delay=20;return;}if(poll==4&&encounter.isBlank()){MODEL.endEncounter();poll=0;delay=12;return;}
        JsonObject a=switch(op){case ACTIVE->args();case CAMPAIGN_GET->args("campaign",MODEL.campaign());case PARTY->args("campaign",MODEL.campaign(),"page",partyPages.page());case EVENTS->args("campaign",MODEL.campaign(),"cursor",MODEL.cursor(),"kind",null);default->args("encounter",encounter);};long token=generation;pending=true;
        UiRequestQueue.enqueue(op,a,()->token==generation,reply->{pending=false;delay=12;if(!reply.code().equals("OK")){if(reply.code().equals("RATE_LIMIT")){delay=40;error="The server is busy; HUD refresh will resume shortly.";return;}if(op==INITIATIVE){MODEL.endEncounter();encounter="";}else{clear();delay=40;}return;}lease=ticks+100;var d=reply.data();try{switch(op){case ACTIVE->{String c=text(d,"campaign");if(!MODEL.campaign().equals(c)){DiceAnimation.invalidatePrivate();dice=null;notice=null;fallback.clear();log=List.of();role="";}if(!MODEL.campaign().equals(c))partyPages.clear();MODEL.campaign(c);combat=flag(d,"inCombat")||ClientSrdCombat.hudEncounter()!=null;encounter=ClientSrdCombat.hudEncounter()!=null?ClientSrdCombat.hudEncounter().toString():ClientCombatState.active?ClientCombatState.hudEncounter().toString():"";lease=ticks+100;if(!combat)MODEL.endEncounter();}case CAMPAIGN_GET->{String r=flag(d,"manager")+":"+revision(d);if(!role.isEmpty()&&!role.equals(r)){DiceAnimation.invalidatePrivate();partyPages.clear();MODEL.party(new JsonObject());MODEL.invalidateHistory();dice=null;notice=null;log=List.of();}role=r;}case PARTY->{var combined=partyPages.accept(d);if(combined!=null)MODEL.party(combined);else if(partyPages.restarted())MODEL.party(new JsonObject());}case EVENTS->{MODEL.events(d,ticks,options().bubbleTicks());log=MODEL.history(HudSession.Filter.ALL);if(array(d,"events").size()==16){poll=2;}}case INITIATIVE->MODEL.initiative(encounter,d);default->{}}poll=(poll+1)%5;}catch(RuntimeException invalid){clear();delay=40;error="Invalid HUD readback; refresh required.";}});
    }
    public static void legacy(dev.tacticalcombat.net.DiceRollPayload payload){if(options().legacyDice()){DiceAnimation.enqueue(payload);return;}if(campaignEvents())return;UiEvents.Roll roll=UiEvents.Roll.from(payload.type().sides,Arrays.stream(payload.results()).boxed().toList(),payload.keep(),payload.modifier(),payload.label(),false);var e=new HudSession.Line(UUID.randomUUID(),0,"DICE",payload.roller(),List.of(),roll);if(dice==null){dice=e;diceStart=ticks;}else legacyQueue(e);}
    private static final ArrayDeque<HudSession.Line> fallback=new ArrayDeque<>();
    private static void legacyQueue(HudSession.Line e){if(fallback.size()>=8)fallback.removeFirst();fallback.addLast(e);}
    public static void render(DrawContext g,RenderTickCounter counter){var mc=MinecraftClient.getInstance();if(mc.player==null||mc.options.hudHidden||!preferences().visible()||mc.currentScreen!=null&&!(mc.currentScreen instanceof TacticalScreen))return;draw(g,false);}
    public static Map<String,UiLayout.Rect> rectangles(int w,int h){var p=preferences();var map=new LinkedHashMap<String,UiLayout.Rect>();map.put("party",HudSession.bounds(p.party(),w,h,174,Math.max(48,24+Math.min(8,MODEL.members().size())*27)));map.put("initiative",HudSession.initiativeBounds(p,w,h,map.get("party")));map.put("dice",HudSession.bounds(p.dice(),w,h,222,94));map.put("events",HudSession.bounds(p.events(),w,h,270,expanded?130:76));map.put("notifications",HudSession.bounds(options().notifications(),w,h,210,36));return map;}
    public static void draw(DrawContext g,boolean editing){var mc=MinecraftClient.getInstance();var p=preferences();var o=options();var rect=rectangles(g.getScaledWindowWidth(),g.getScaledWindowHeight());if(editing||p.party().visible()&&(combat||o.outsideCombat())){var r=rect.get("party");try(var clip=panel(g,r,"PARTY · "+MODEL.members().size()+(partyPages.loading()?" · loading":""))){int y=r.y()+16;for(var member:MODEL.members()){if(y+24>r.y()+r.height())break;var actor=MODEL.actors().stream().filter(a->a.id().equals(member.actor())).findFirst().orElse(null);String first=member.name()+(member.online()?"":" · offline")+(combat&&actor!=null?" · "+actor.initiative():"");text(g,first,r.x()+5,y,r.width()-10,o.partyFont(),actor!=null&&actor.active()?RpgTheme.GOLD:RpgTheme.TEXT);text(g,member.health()+" · "+member.characterClass(),r.x()+5,y+10,r.width()-10,o.partyFont(),RpgTheme.MUTED);if(member.fraction()>=0){g.fill(r.x()+5,y+21,r.x()+r.width()-5,y+23,0xFF33383D);g.fill(r.x()+5,y+21,r.x()+5+(int)((r.width()-10)*member.fraction()),y+23,0xFF6C9778);}var bubble=MODEL.bubble(member.actor(),ticks);if(bubble!=null)text(g,bubble.text(),r.x()+5,y+10,r.width()-10,o.partyFont(),RpgTheme.GOLD);else if(!member.conditions().isEmpty())text(g,String.join(", ",member.conditions()),r.x()+5,y+10,r.width()-10,o.partyFont(),RpgTheme.MUTED);y+=27;}int shown=Math.max(0,(r.height()-20)/27);if(MODEL.members().size()>shown)text(g,"+"+(MODEL.members().size()-shown)+" · L for full party",r.x()+5,r.y()+r.height()-9,r.width()-10,8,RpgTheme.GOLD);}}
        if(editing||p.initiative().visible()&&!MODEL.actors().isEmpty()){var r=rect.get("initiative");try(var clip=panel(g,r,"INITIATIVE"+(MODEL.round()>0?" · round "+MODEL.round():""))){int capacity=Math.max(1,(r.width()-10)/70),active=0;for(int i=0;i<MODEL.actors().size();i++)if(MODEL.actors().get(i).active())active=i;for(int i=0;i<Math.min(capacity,MODEL.actors().size());i++){var a=MODEL.actors().get((active+i)%MODEL.actors().size());text(g,a.name()+" "+a.initiative(),r.x()+5+i*70,r.y()+18,66,8,a.active()?RpgTheme.GOLD:RpgTheme.TEXT);}if(MODEL.actors().size()>capacity)text(g,"+"+(MODEL.actors().size()-capacity),r.x()+r.width()-28,r.y()+4,24,8,RpgTheme.MUTED);}}
        if(editing||p.dice().visible()&&dice!=null){var r=rect.get("dice");try(var clip=panel(g,r,"DICE")){if(dice!=null){var roll=dice.roll();double progress=Math.min(1,(ticks-diceStart)/(double)animationTicks());int count=roll.faces().size(),size=Math.min(28,(r.width()-12)/Math.max(1,count)-4);for(int i=0;i<count;i++){int x=r.x()+8+i*(size+4),y=r.y()+20;g.getMatrices().push();g.getMatrices().translate(x+size/2f,y+size/2f,0);if(!p.reducedMotion())g.getMatrices().multiply(net.minecraft.util.math.RotationAxis.POSITIVE_Z.rotation((float)((1-progress)*Math.PI*4)));int color=roll.kept().contains(i)?RpgTheme.GOLD:RpgTheme.MUTED;g.fill(-size/2-1,-size/2-1,size/2+1,size/2+1,color);g.fill(-size/2,-size/2,size/2,size/2,RpgTheme.PANEL);String face=progress>=1?Integer.toString(roll.faces().get(i)):Integer.toString(1+(int)((ticks+i*7)%roll.sides()));g.drawCenteredTextWithShadow(mc.textRenderer,face,0,-4,color);g.getMatrices().pop();}text(g,roll.purpose().isBlank()?dice.summary():roll.purpose(),r.x()+5,r.y()+52,r.width()-10,o.diceFont(),RpgTheme.TEXT);text(g,progress>=1?dice.calculation():"Rolling…",r.x()+5,r.y()+66,r.width()-10,o.diceFont(),RpgTheme.GOLD);if(progress>=1&&HudSession.natural(roll)!=0)text(g,(roll.critical()?"Critical · ":"")+"natural "+HudSession.natural(roll),r.x()+5,r.y()+80,r.width()-10,8,RpgTheme.MUTED);}}}
        if(editing||p.events().visible()&&!log.isEmpty()){var r=rect.get("events");try(var clip=panel(g,r,"EVENTS · L to expand")){int capacity=Math.max(1,(r.height()-20)/11),start=Math.max(0,log.size()-capacity),y=r.y()+17;for(int i=start;i<log.size();i++){var line=log.get(i);text(g,line.sequence()+" · "+line.kind()+" · "+(line.roll()==null?line.summary():line.calculation()),r.x()+5,y,r.width()-10,o.logFont(),RpgTheme.TEXT);y+=11;}}}
        if(editing||o.notificationsVisible()&&notice!=null){var r=rect.get("notifications");try(var clip=panel(g,r,"NOTICE")){if(notice!=null)text(g,notice.kind().equals("TURN")&&mc.player!=null&&notice.actors().contains(mc.player.getUuidAsString())?"Your turn · "+notice.summary():notice.summary(),r.x()+5,r.y()+17,r.width()-10,9,RpgTheme.GOLD);}}
    }
    private static ClipScope panel(DrawContext g,UiLayout.Rect r,String label){RpgTheme.panel(g,r.x(),r.y(),r.width(),r.height(),0xCE191D23,false);var clip=ClipScope.open(()->g.enableScissor(r.x(),r.y(),r.x()+r.width(),r.y()+r.height()),g::disableScissor);try{text(g,label,r.x()+5,r.y()+4,r.width()-10,8,RpgTheme.GOLD);return clip;}catch(RuntimeException|Error failure){clip.close();throw failure;}}
    private static String text(JsonObject data,String key){return ManagementState.text(data,key);}
    private static void text(DrawContext g,String value,int x,int y,int width,int size,int color){float scale=(size/9f)*(preferences().fontSize()/9f);var tr=MinecraftClient.getInstance().textRenderer;String fitted=tr.trimToWidth(value,Math.max(1,(int)(width/scale)));g.getMatrices().push();g.getMatrices().translate(x,y,0);g.getMatrices().scale(scale,scale,1);g.drawText(tr,fitted,0,0,color,false);g.getMatrices().pop();}
}
